// Applica le modifiche: chat di creazione viaggio (ramo prenotazioni completo).
// Uso: salva nella cartella RADICE del progetto e lancia:  node applica-modifiche.js
import { writeFileSync, mkdirSync, readFileSync } from 'fs'
import { dirname } from 'path'

const files = {
  "src/components/ChatNuovoViaggio.jsx": '',
  "src/components/ChatNuovoViaggio.css": '',
  "src/pages/Home.jsx": '',
}

for (const [percorso, b64] of Object.entries(files)) {
  mkdirSync(dirname(percorso), { recursive: true })
  writeFileSync(percorso, Buffer.from(b64, 'base64'))
  console.log('scritto:', percorso)
}

const home = readFileSync('src/pages/Home.jsx', 'utf8')
console.log(home.includes('ChatNuovoViaggio')
  ? '\nVERIFICA OK — chat agganciata a Home.jsx.'
  : '\nATTENZIONE — aggancio mancante: stai eseguendo una versione vecchia dello script.')
console.log('Ora: git add . && git commit -m "chat creazione viaggio" && git push')